-- Smart categorising (docs/plans/smart-categorisation.md). Hand-written additions to what drizzle-kit made.

-- Stable keys for the default categories, so the bundled shop catalog keeps working after a rename.
UPDATE "categories" SET "slug" = v.slug FROM (VALUES
  ('Huur', 'rent'), ('Gas, water, licht', 'utilities'), ('Internet & telefoon', 'internet-phone'),
  ('Zorgverzekering', 'health-insurance'), ('Boodschappen', 'groceries'), ('Eten & drinken', 'eating-out'),
