  ('Gezondheid', 'health'), ('Reizen & vakantie', 'travel'), ('Cadeaus & donaties', 'gifts-donations'),
  ('Sparen & beleggen', 'saving-investing'), ('Overig', 'other'), ('Salaris / bijbaan', 'salary'),
  ('Studiefinanciering (DUO)', 'student-finance'), ('Zorgtoeslag', 'care-allowance'),
  ('Huurtoeslag', 'rent-allowance'), ('Familie / gift', 'family-gift'), ('Overig inkomen', 'other-income'),
  ('Interne overboeking', 'internal-transfer')
) AS v(name, slug) WHERE "categories"."name" = v.name AND "categories"."slug" IS NULL;
