-- Supabase hands new tables to its API roles by default; take it away again (see 0002).
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon')
     AND EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN
    REVOKE ALL ON "merchant_labels", "user_settings", "ai_usage" FROM anon, authenticated;
    REVOKE ALL ON SEQUENCE "merchant_labels_id_seq" FROM anon, authenticated;
  END IF;
END
$$;
